package com.gameaggregator.deploymentservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="deployments") public class Deployment{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID releaseId;@Column(nullable=false)public UUID environmentId;@Enumerated(EnumType.STRING)@Column(nullable=false)public DeploymentStatus status=DeploymentStatus.PENDING;@Column(nullable=false)public UUID requestedBy;@Column(nullable=false)public Instant createdAt=Instant.now();public Instant startedAt;public Instant finishedAt;@Version public long revision;protected Deployment(){}public Deployment(UUID r,UUID e,UUID u){releaseId=r;environmentId=e;requestedBy=u;}}